//! 🤝️ OS guest publication composes the defining General Actor authority without a reverse source mount.
use super::super as guest_context;
use semio_framework_actor::{ActorGuestPhase,OriginalActorInput,RetainedTurnInput};
use semio_framework_actor::retained_turn::OriginalActorTurnWork;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
fn grant(row:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize}}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_plugin_bootstrap_honors_scoped_work_before_context_or_bundle_birth(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("scoped-budget.json")).unwrap();let grant=RetainedCloneGrant{maximum_items:65536,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:128};
 for row in fixture["cases"].as_array().unwrap(){let mut input=RetainedTurnInput{operation:719,generation:1,epoch:1,work:OriginalActorTurnWork{clock_binding:719,absolute_deadline_us:1000,fuel:100},grant};let mut entry=guest_context::OriginalActorGuestEntry::new();let budget=semio_framework_actor::OriginalJobBudget{input,retained_policy:grant,fuel:row["fuel"].as_u64().unwrap(),deadline_us:row["deadline"].as_u64().unwrap(),cancelled:row["cancelled"].as_bool().unwrap()};let mut ensures=0;let(call,heap)=observe(||entry.admit_plugin_step(budget,||Some(10),|_|{ensures+=1;Ok(())}));assert_eq!(call.input,input);assert_eq!(call.result.is_ok(),row["accepted"].as_bool().unwrap());assert_eq!(call.work_units_spent!=0,row["mayAdvance"].as_bool().unwrap());assert!(call.work_units_spent<=budget.fuel);assert_eq!(heap,(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));assert_eq!(ensures,0);let returned=input.return_original(call.receipt_spent,call.work_units_spent).unwrap();input.grant=returned.remaining;input.work.fuel=returned.remaining_fuel;
  while !entry.terminal_is_empty(){input.epoch+=1;let(call,heap)=observe(||entry.close_plugin_step(semio_framework_actor::OriginalJobBudget{input,retained_policy:input.grant,fuel:1,deadline_us:10,cancelled:true}));assert!(call.result.is_ok());assert!(call.work_units_spent<=1);assert_eq!(heap,(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));let returned=input.return_original(call.receipt_spent,call.work_units_spent).unwrap();input.grant=returned.remaining;input.work.fuel=returned.remaining_fuel;}assert_eq!(observe(||drop(entry)).1,(0,0));
 }
}
#[test]
fn original_public_actor_guest_entry_keeps_same_fault_and_raw_receipts_through_paid_native_publication(){
 use semio_framework_value::FromValue;
 use semio_framework_job::{StepBudget,JobOutcomeView};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 let canonical:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../🔨️modules/⚠️diagnostic/🧪️tests/🧫️fixtures/🧯️fault/🔣️.json")).unwrap();
 let row=&canonical["cases"][0];let(original_fault,source_heap)=observe(||semio_framework_diagnostic::Fault::from_value(serde_json::from_value(row["input"].clone()).unwrap()).unwrap());let source_net=source_heap.0.checked_sub(source_heap.1).unwrap();let source_message=original_fault.message.as_ptr();let mut pending_fault=Some(original_fault);
 let mut incoming=RetainedTurnInput{operation:71,generation:3,epoch:19,work:OriginalActorTurnWork{clock_binding:1,absolute_deadline_us:u64::MAX,fuel:1000},grant:grant(&fixture["entryOriginalAuthority"])};let(mut host,heap)=observe(||OriginalActorInput::new((),incoming).ok().unwrap());assert_eq!(heap,(0,0));let(mut guest,heap)=observe(guest_context::OriginalActorGuestEntry::new);assert_eq!(heap,(0,0));let mut born=0;let mut released=0;let mut ready=false;
 while !ready{let policy=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,..incoming.grant};let checked=host.checkout_guest(policy).unwrap().unwrap();let(call,heap)=observe(||guest.admit_step(checked,policy,semio_framework_job::logical_now_us));assert_eq!(heap,(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=heap.0;released+=heap.1;let reply=semio_framework_actor::retained_context::OriginalActorAdmissionReply::borrow_original(&call);assert_eq!(reply.input,checked);assert_eq!(reply.spent,call.receipt_spent);assert!(reply.refusal.is_none());ready=reply.ready;host.receive_guest(call.receipt().unwrap(),if ready{ActorGuestPhase::Ready}else{ActorGuestPhase::Pending}).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,work:OriginalActorTurnWork{fuel:parent.remaining_fuel,..incoming.work},..incoming};host.receive_next_issued(incoming).unwrap();}
 let checked=host.checkout_guest(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:7,maximum_capacity_bytes:0,maximum_release_bytes:0,..incoming.grant}).unwrap().unwrap();let mut recipient=Default::default();let original_recipient=&mut recipient as*mut _;let(call,heap)=observe(||guest.dispatch_step(checked,StepBudget::new(100,u64::MAX,host.guest_policy(checked).unwrap()),&mut recipient,semio_framework_job::logical_now_us,|cx|{cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()}).unwrap();Err::<(),_>(pending_fault.take().unwrap())}));assert_eq!(heap,(0,0));assert!(matches!(call.result,Err(guest_context::OriginalActorEntryFailure::Semantic)));assert_eq!(call.receipt_spent,RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()});assert_eq!(guest.original_fault().unwrap().message.as_ptr(),source_message);let fault_pointer=guest.original_fault().unwrap()as*const _;host.receive_guest(call.receipt().unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,work:OriginalActorTurnWork{fuel:parent.remaining_fuel,..incoming.work},..incoming};host.receive_next_issued(incoming).unwrap();
 let mut failure_binding=None;let checked=host.checkout_guest(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1024,..incoming.grant}).unwrap().unwrap();recipient=Default::default();let(call,heap)=observe(||guest.dispatch_cleanup_value_step(checked,StepBudget::new(100,u64::MAX,host.guest_policy(checked).unwrap()),&mut recipient,semio_framework_job::logical_now_us,|cx|cx.with_original_retirement(|cx|{let bytes=std::mem::size_of::<Option<semio_framework_job::OriginalSourceBinding>>();cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:bytes,..Default::default()})?;cx.consume_fuel(1);failure_binding=Some(semio_framework_job::OriginalSourceBinding::borrow(cx));Ok::<_,semio_framework_job::OriginalTurnFailure>(true)})));assert!(matches!(call.result,Ok(true)));assert_eq!(heap,(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));assert_eq!(guest.original_fault().unwrap()as*const _,fault_pointer);host.receive_guest(call.receipt().unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,work:OriginalActorTurnWork{fuel:parent.remaining_fuel,..incoming.work},..incoming};host.receive_next_issued(incoming).unwrap();
 let mut descriptor=None;let mut turns=0;while descriptor.is_none(){let checked=host.checkout_guest(RetainedCloneGrant{maximum_items:4,maximum_copy_bytes:1024,..incoming.grant}).unwrap().unwrap();recipient=Default::default();let(call,heap)=observe(||guest.publish_failure_into(checked,StepBudget::new(100,u64::MAX,host.guest_policy(checked).unwrap()),&mut recipient,semio_framework_job::logical_now_us,failure_binding.unwrap(),&mut descriptor));assert_eq!(heap,(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));assert_eq!(&mut recipient as*mut _,original_recipient);born+=heap.0;released+=heap.1;let receipt=call.receipt().unwrap();assert_eq!(call.result.unwrap(),descriptor.is_some());assert_eq!(guest.original_fault().unwrap()as*const _,fault_pointer);assert_eq!(guest.original_fault().unwrap().message.as_ptr(),source_message);host.receive_guest(receipt,ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,work:OriginalActorTurnWork{fuel:parent.remaining_fuel,..incoming.work},..incoming};host.receive_next_issued(incoming).unwrap();turns+=1;assert!(turns<1024);}
 let mut descriptor=descriptor.unwrap();let view=guest.borrow_failure_outcome(&descriptor).unwrap();let payload=match view{JobOutcomeView::Fault{detail,..}=>detail,_=>panic!("original guest fault descriptor required")};let mut bytes=Vec::with_capacity(payload.len());for index in 0..payload.page_count(){bytes.extend_from_slice(payload.page(index).unwrap())}assert_eq!(serde_json::from_slice::<serde_json::Value>(&bytes).unwrap(),row["expected"]);drop(bytes);
 let checked=host.checkout_guest(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,..incoming.grant}).unwrap().unwrap();let(step,heap)=observe(||descriptor.acknowledge(checked.grant).result.unwrap());assert_eq!(heap,(0,0));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert!(descriptor.is_acknowledged());host.receive_guest(checked.return_original(step.progress(),0).unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,work:OriginalActorTurnWork{fuel:parent.remaining_fuel,..incoming.work},..incoming};host.receive_next_issued(incoming).unwrap();assert_eq!(observe(||drop(descriptor)).1,(0,0));host.take_dispatched_input().unwrap();
 let mut closes=0;while !guest.terminal_is_empty(){let checked=host.checkout_guest(RetainedCloneGrant{maximum_items:1,..incoming.grant}).unwrap().unwrap();let(call,heap)=observe(||guest.close_step(checked,host.guest_policy(checked).unwrap()));assert_eq!(heap,(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=heap.0;released+=heap.1;let receipt=call.receipt().unwrap();assert!(call.result.is_ok());host.receive_guest(receipt,ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,work:OriginalActorTurnWork{fuel:parent.remaining_fuel,..incoming.work},..incoming};host.receive_next_issued(incoming).unwrap();closes+=1;assert!(closes<256);}
 assert_eq!(released,born+source_net);assert_eq!(observe(||drop(guest)).1,(0,0));assert_eq!(observe(||drop(host)).1,(0,0));
}

#[test]
fn original_plugin_publisher_receipt_failure_retains_complete_cause(){
 use semio_framework_job::StepBudget;
 fn next(input:&mut RetainedTurnInput,spent:RetainedCloneProgress,work:u64){let returned=input.return_original(spent,work).unwrap();input.epoch+=1;input.grant=returned.remaining;input.work.fuel=returned.remaining_fuel;}
 let stock=RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:64};let mut input=RetainedTurnInput{operation:8850,generation:1,epoch:1,work:OriginalActorTurnWork{clock_binding:8850,absolute_deadline_us:10000,fuel:10000},grant:stock};let mut entry=guest_context::OriginalActorGuestEntry::new();
 for _ in 0..64{if entry.context.is_ready(){break}let q=RetainedCloneGrant{maximum_items:1,..input.grant};let call=entry.admit_step(input,q,||Some(1));assert!(call.result.is_ok());next(&mut input,call.receipt_spent,call.work_units_spent)}assert!(entry.context.is_ready());
 let mut table=false;for _ in 0..64{let q=RetainedCloneGrant{maximum_items:1,..input.grant};let mut receipt=RetainedCloneProgress::default();let call=entry.context.dispatch_step(input,StepBudget::new(input.work.fuel,input.work.absolute_deadline_us,q),&mut receipt,||Some(1),|cx|{if !cx.admit_original_core_wire_delivery()?{return Ok(false)}cx.admit_original_return_table()});table=call.result.unwrap();next(&mut input,call.receipt_spent,call.work_units_spent);if table{break}}assert!(table);
 let q=RetainedCloneGrant{maximum_items:1,..input.grant};semio_framework_job::testkit::set_loan_receipt_refusal(true);let call=entry.admit_plugin_step(semio_framework_actor::OriginalJobBudget{input,retained_policy:q,fuel:input.work.fuel,deadline_us:input.work.absolute_deadline_us,cancelled:false},||Some(1),|_|Ok(()));assert!(call.result.is_err());assert!(call.receipt_spent.retained_capacity_bytes>0);next(&mut input,call.receipt_spent,call.work_units_spent);let retained=entry.original_job_refusal().expect("complete original publisher refusal") as *const _;assert!(entry.original_job_refusal().unwrap().primary_value().is_some());
 let q=RetainedCloneGrant{maximum_items:1,..input.grant};let retry=entry.admit_plugin_step(semio_framework_actor::OriginalJobBudget{input,retained_policy:q,fuel:input.work.fuel,deadline_us:input.work.absolute_deadline_us,cancelled:false},||Some(1),|_|Ok(()));assert!(retry.result.is_err());assert_eq!(retry.receipt_spent,RetainedCloneProgress::default());assert_eq!(entry.original_job_refusal().unwrap() as *const _,retained);next(&mut input,retry.receipt_spent,retry.work_units_spent);
 for _ in 0..1024{if entry.terminal_is_empty(){break}let q=RetainedCloneGrant{maximum_items:1,..input.grant};let call=entry.close_plugin_step(semio_framework_actor::OriginalJobBudget{input,retained_policy:q,fuel:input.work.fuel,deadline_us:input.work.absolute_deadline_us,cancelled:true});assert!(call.result.is_ok());next(&mut input,call.receipt_spent,call.work_units_spent)}assert!(entry.terminal_is_empty());
}

#[test]
fn original_core_wire_scope_withholds_real_reserve(){
 use semio_framework_job_testing_caller::OriginalJobFixtureCaller;use semio_framework_job::{OperationId,Generation};use semio_framework_job_return_escrow_publication::OriginalEscrowPublisher;
 let demand=OriginalEscrowPublisher::core_wire_reserve(144).unwrap();let stock=RetainedCloneGrant{maximum_items:4096,maximum_copy_bytes:1048576,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:64};let mut caller=OriginalJobFixtureCaller::admit(OperationId(8860),Generation(10),stock,||Some(1),10000,10000);let mut called=false;
 let denied=RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..stock};caller.turn(denied,|cx|{let before=cx.retained_progress();assert!(guest_context::with_core_wire_reserve(cx,144,|_|{called=true;Ok(())}).is_err());assert_eq!(cx.retained_progress(),before);Ok(())}).unwrap();assert!(!called);
 caller.turn(stock,|cx|{let before=cx.retained_progress();let grant=cx.retained_grant();let fuel=cx.fuel_remaining();guest_context::with_core_wire_reserve(cx,144,|inner|{called=true;assert_eq!(inner.retained_grant().maximum_items,grant.maximum_items-demand.items);assert_eq!(inner.retained_grant().maximum_copy_bytes,grant.maximum_copy_bytes-demand.copy_bytes);assert!(inner.fuel_remaining()<=fuel-demand.work);Ok(())})?;assert_eq!(cx.retained_progress(),before);Ok(())}).unwrap();assert!(called);caller.retire(stock);
}
